// Fast Index Maps for O(1) Lookups
const _productById = new Map();
const _productByCanonicalKey = new Map();
const _productBySeoSlug = new Map();
const _productByLegacyPath = new Map();

ALL_SEO_PRODUCTS.forEach(p => {
  _productById.set(p.id, p);
  if (p.gradeSlug) {
    _productByCanonicalKey.set(`${p.division}:${p.gradeSlug}`, p);
    _productByCanonicalKey.set(`${p.division}:${p.categorySlug}:${p.gradeSlug}`, p);
    if (p.division === 'buttweld-fittings') {
      _productByCanonicalKey.set(`pipe-fittings:${p.gradeSlug}`, p);
      _productByCanonicalKey.set(`pipe-fittings:${p.categorySlug}:${p.gradeSlug}`, p);
    }
    if (p.materialSlug) {
      _productByCanonicalKey.set(`${p.division}:${p.materialSlug}:${p.gradeSlug}`, p);
    }
  }
  if (p.typeSlug) {
    _productByCanonicalKey.set(`${p.division}:${p.materialSlug}:${p.typeSlug}`, p);
    _productByCanonicalKey.set(`${p.division}:${p.typeSlug}`, p);
  }

  _productBySeoSlug.set(p.seoSlug.toLowerCase(), p);
  _productBySeoSlug.set(`${p.seoSlug}-${p.suffix}`.toLowerCase(), p);
  const altSuffix = p.suffix === SUFFIX_MANUFACTURED ? SUFFIX_STOCKIST : SUFFIX_MANUFACTURED;
  _productBySeoSlug.set(`${p.seoSlug}-${altSuffix}`.toLowerCase(), p);

  _productByLegacyPath.set(p.canonicalUrl.toLowerCase(), p);
  _productByLegacyPath.set(`${p.canonicalUrl.replace(p.suffix, altSuffix)}`.toLowerCase(), p);

  if (p.legacyUrls) {
    p.legacyUrls.forEach(legacy => {
      _productByLegacyPath.set(legacy.toLowerCase(), p);
      _productByLegacyPath.set(`${legacy}-${SUFFIX_MANUFACTURED}`.toLowerCase(), p);
      _productByLegacyPath.set(`${legacy}-${SUFFIX_STOCKIST}`.toLowerCase(), p);
    });
  }
});

