EXPLICIT_PROMPT_ALIASES.forEach(item => {
  const target = _productById.get(item.id);
  if (target) {
    (item.urls || []).forEach(u => _productByLegacyPath.set(u.toLowerCase(), target));
    (item.slugs || []).forEach(s => {
      _productBySeoSlug.set(s.toLowerCase(), target);
      _productBySeoSlug.set(`${s}-${SUFFIX_MANUFACTURED}`.toLowerCase(), target);
      _productBySeoSlug.set(`${s}-${SUFFIX_STOCKIST}`.toLowerCase(), target);
    });
  }
});

export function stripSeoSuffix(slug = "") {
  if (!slug || typeof slug !== "string") return "";
  return slug
    .replace(new RegExp(`-${SUFFIX_MANUFACTURED}$`, "i"), "")
    .replace(new RegExp(`-${SUFFIX_STOCKIST}$`, "i"), "")
    .replace(new RegExp(`^${SUFFIX_MANUFACTURED}$`, "i"), "")
    .replace(new RegExp(`^${SUFFIX_STOCKIST}$`, "i"), "");
}

export function getProductByCanonicalKey(division, materialOrCategory, gradeOrType) {
  if (!division) return null;
  const k1 = `${division}:${materialOrCategory}:${gradeOrType}`;
  if (_productByCanonicalKey.has(k1)) return _productByCanonicalKey.get(k1);

  const k2 = `${division}:${gradeOrType}`;
  if (_productByCanonicalKey.has(k2)) return _productByCanonicalKey.get(k2);

  return null;
}

export function resolveProductFromPath(pathOrUrl = "") {
  if (!pathOrUrl || typeof pathOrUrl !== "string") return null;

  const clean = pathOrUrl.split("?")[0].split("#")[0].toLowerCase().trim();

  if (_productByLegacyPath.has(clean)) {
    return _productByLegacyPath.get(clean);
  }

  const segments = clean.replace(/^\/products\/?/i, "").split("/").filter(Boolean);
  if (segments.length === 0) return null;

  const rawLast = segments[segments.length - 1];
  const cleanedLast = stripSeoSuffix(rawLast);

  if (_productBySeoSlug.has(cleanedLast)) {
    return _productBySeoSlug.get(cleanedLast);
  }
  if (_productBySeoSlug.has(rawLast)) {
    return _productBySeoSlug.get(rawLast);
  }

  // Normalized fuzzy lookup (e.g., stripping astm-, ss-, etc.)
  const normalizedSlug = cleanedLast
    .replace(/-astm-/g, "-")
    .replace(/^astm-/g, "")
    .replace(/-ss-/g, "-")
    .replace(/^ss-/g, "");

  if (_productBySeoSlug.has(normalizedSlug)) {
    return _productBySeoSlug.get(normalizedSlug);
  }

  if (segments.length >= 2) {
    const p0 = segments[0];
    const p1 = stripSeoSuffix(segments[1]);
    const p2 = segments[2] ? stripSeoSuffix(segments[2]) : null;

    if (p2) {
      const match = getProductByCanonicalKey(p0, p1, p2);
      if (match) return match;
    }

    const match2 = getProductByCanonicalKey(p0, null, p1);
    if (match2) return match2;
  }

  return null;
}

export function getCanonicalProductUrl({ division, categorySlug, materialSlug, gradeSlug, typeSlug, fallbackUrl }) {
  const product = getProductByCanonicalKey(division, materialSlug || categorySlug, gradeSlug || typeSlug);
  if (product) return product.canonicalUrl;
  return fallbackUrl || null;
}

